tool_input.command:
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# check tool-set consistency across several sessions of different models
$files = Get-ChildItem $dir -Filter "session-*.json" | Get-Random -Count 8
foreach($f in $files){
  $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
  $hs = $j.record.rows.contextHeaders.val.headers
  if($hs -and $hs.Count -gt 0){
    $t = $hs[0].tools
    $m = $j.record.rows.modelSelection.val.lastUsed
    Write-Host ("{0} model={1}/{2} toolCount={3} toolTokensSum={4} headersCount={5}" -f $f.Name.Substring(8,8),$m.provider,$m.model,$t.Count,(($t|Measure-Object -Property tokens -Sum).Sum),$hs.Count)
  }
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"
$total=0; $withOV=0; $sumTok=0; $sumTokOV=0; $ovSum=0
$samples=@()
foreach($f in $files){
  try{
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $hs = $j.record.rows.contextHeaders.val.headers
    if(-not $hs -or $hs.Count -eq 0){continue}
    $t = $hs[0].tools
    if(-not $t){continue}
    $total++
    $s = ($t|Measure-Object -Property tokens -Sum).Sum
    $sumTok += $s
    $ov = $t | Where-Object { $_.name -like 'mcp__openviking__*' }
    if($ov){ $withOV++; $ovSum += ($ov|Measure-Object -Property tokens -Sum).Sum; $samples+=$s }
  }catch{}
}
Write-Host ("sessions with tool headers: {0}" -f $total)
Write-Host ("sessions carrying mcp__openviking__* tools: {0} ({1:N0}%)" -f $withOV,(100*$withOV/$total))
Write-Host ("avg tool tokens (all): {0:N0}" -f ($sumTok/$total))
Write-Host ("avg ov-tool tokens in those sessions: {0:N0}" -f ($ovSum/[Math]::Max(1,$withOV)))

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# Aggregate tool-result token sizes by tool across a sample of sessions' contextTimeline
$files = Get-ChildItem $dir -Filter "session-*.json" | Get-Random -Count 120
$toolSizes=@{}
$toolCounts=@{}
foreach($f in $files){
  try{
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $tl = $j.record.rows.contextTimeline.val.surface
    if(-not $tl){continue}
    foreach($e in $tl){
      if($e.cat -eq 'tool' -and $e.tool){
        $toolSizes[$e.tool] += [double]$e.tokens
        $toolCounts[$e.tool] += 1
      }
    }
  }catch{}
}
Write-Host "=== tool result tokens (total over 120 sessions) sorted desc ==="
$toolSizes.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 20 | ForEach-Object {
  "{0,-28} total={1,10:N0}  calls={2,6}  avg={3,7:N0}" -f $_.Key,$_.Value,$toolCounts[$_.Key],($_.Value/[Math]::Max(1,$toolCounts[$_.Key]))
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json" | Get-Random -Count 150
$rows=@()
foreach($f in $files){
  try{
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $tl = $j.record.rows.contextTimeline.val.surface
    if(-not $tl){continue}
    foreach($e in $tl){ if($e.cat -eq 'tool' -and $e.tool){ $rows += [pscustomobject]@{tool=$e.tool;tok=[double]$e.tokens} } }
  }catch{}
}
$g = $rows | Group-Object tool | ForEach-Object {
  [pscustomobject]@{tool=$_.Name; total=($_.Group|Measure-Object tok -Sum).Sum; calls=$_.Count; avg=[math]::Round(($_.Group|Measure-Object tok -Average).Average)}
}
$g | Sort-Object total -Descending | Select-Object -First 18 | Format-Table -AutoSize

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json" | Get-Random -Count 150
$acc = @{}
foreach($f in $files){
  try{
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $tl = $j.record.rows.contextTimeline.val.surface
    if(-not $tl){continue}
    foreach($e in $tl){
      if($e.cat -eq 'tool' -and $e.tool){
        $k=[string]$e.tool
        if(-not $acc.ContainsKey($k)){ $acc[$k]=@{tot=0.0;n=0} }
        $acc[$k].tot += [double]$e.tokens
        $acc[$k].n += 1
      }
    }
  }catch{}
}
$acc.GetEnumerator() | Sort-Object { $_.Value.tot } -Descending | Select-Object -First 18 | ForEach-Object {
  $avg = if($_.Value.n -gt 0){[math]::Round($_.Value.tot/$_.Value.n)}else{0}
  "{0,-24} total={1,10:N0}  calls={2,6}  avg={3,8:N0}" -f $_.Key,$_.Value.tot,$_.Value.n,$avg
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json" | Get-Random -Count 150
$tot=@{user=0.0;inject=0.0;skill=0.0;assistant=0.0;tool=0.0}; $n=0
foreach($f in $files){
  try{
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $s = $j.record.rows.contextTimeline.val.sums
    if(-not $s){continue}
    $n++
    foreach($k in 'user','inject','skill','assistant','tool'){ if($s.$k){$tot[$k]+=[double]$s.$k} }
  }catch{}
}
Write-Host "sessions: $n  (avg per session by category, tokens)"
$grand = ($tot.Values | Measure-Object -Sum).Sum
foreach($k in 'inject','tool','assistant','user','skill'){
  "{0,-10} avg={1,10:N0}  share={2,5:N1}%" -f $k,($tot[$k]/$n),(100*$tot[$k]/$grand)
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json" | Get-Random -Count 150
$tot=[ordered]@{inject=0.0;tool=0.0;assistant=0.0;user=0.0;skill=0.0}; $n=0
foreach($f in $files){
  try{
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $cv = $j.record.rows.contextTimeline.val
    if($cv.PSObject.Properties.Name -contains 'val'){ $s = $cv.val.sums } else { $s = $cv.sums }
    if(-not $s){continue}
    $n++
    if($s.inject){$tot.inject += [double]$s.inject}
    if($s.tool){$tot.tool += [double]$s.tool}
    if($s.assistant){$tot.assistant += [double]$s.assistant}
    if($s.user){$tot.user += [double]$s.user}
    if($s.skill){$tot.skill += [double]$s.skill}
  }catch{}
}
$grand = ($tot.Values | Measure-Object -Sum).Sum
Write-Host "sessions: $n"
foreach($k in $tot.Keys){ "{0,-10} avg={1,10:N0}  share={2,5:N1}%" -f $k,($tot[$k]/$n),(100*$tot[$k]/[Math]::Max(1,$grand)) }

