$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"
$withOV=@{n=0;inj=0.0;tools=0.0;steps=0.0;tot=0.0}
$noOV=@{n=0;inj=0.0;tools=0.0;steps=0.0;tot=0.0}
foreach($f in $files){
  try{
    $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
    $rows=$j.record.rows
    $hs=$rows.contextHeaders.val.headers
    if(-not $hs -or $hs.Count -eq 0){continue}
    $t=$hs[0].tools; if(-not $t){continue}
    $hasOV = ($t | Where-Object {$_.name -like 'mcp__openviking__*'}).Count -gt 0
    $b=$rows.contextBreakdown.val.breakdown
    if(-not $b){continue}
    $st=[double]$rows.sessionStats.val.steps
    if($hasOV){$withOV.n++;$withOV.inj+=[double]$b.systemTokens;$withOV.tools+=[double]$b.toolsTokens;$withOV.steps+=$st}
    else{$noOV.n++;$noOV.inj+=[double]$b.systemTokens;$noOV.tools+=[double]$b.toolsTokens;$noOV.steps+=$st}
  }catch{}
}
Write-Host ("WITH OpenViking tools  : n={0,4} avgTools={1,6:N0} avgSys={2,5:N0} avgSteps={3,5:N1}" -f $withOV.n,($withOV.tools/$withOV.n),($withOV.inj/$withOV.n),($withOV.steps/$withOV.n))
Write-Host ("WITHOUT OpenViking tools: n={0,4} avgTools={1,6:N0} avgSys={2,5:N0} avgSteps={3,5:N1}" -f $noOV.n,($noOV.tools/$noOV.n),($noOV.inj/$noOV.n),($noOV.steps/$noOV.n))
Write-Host ("Delta tools per step: {0:N0}" -f (($withOV.tools/$withOV.n)-($noOV.tools/$noOV.n)))

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"
$wn=0;$wt=0.0;$ws=0.0;$won=0;$wot=0.0;$wos=0.0
foreach($f in $files){
  try{
    $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
    $rows=$j.record.rows
    $hs=$rows.contextHeaders.val.headers
    if(-not $hs){continue}
    if($hs.Count -lt 1){continue}
    $t=$hs[0].tools; if(-not $t){continue}
    $ovc=@($t | Where-Object {$_.name -like 'mcp__openviking__*'}).Count
    $b=$rows.contextBreakdown.val.breakdown; if(-not $b){continue}
    if($ovc -gt 0){ $wn++; $wt+=[double]$b.toolsTokens; $ws+=[double]$b.systemTokens }
    else{ $won++; $wot+=[double]$b.toolsTokens; $wos+=[double]$b.systemTokens }
  }catch{}
}
Write-Host "WITH OV tools: n=$wn avgTools=$([math]::Round($wt/[math]::Max(1,$wn))) avgSys=$([math]::Round($ws/[math]::Max(1,$wn)))"
Write-Host "WITHOUT OV   : n=$won avgTools=$([math]::Round($wot/[math]::Max(1,$won))) avgSys=$([math]::Round($wos/[math]::Max(1,$won)))"
Write-Host "Delta tools: $([math]::Round($wt/[math]::Max(1,$wn) - $wot/[math]::Max(1,$won)))"

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"
$sess=0; $usage=@{}
$toolGroups = @{
  'schedule_*'=@('schedule_create','schedule_delete','schedule_list','schedule_update','schedule_view','schedule_edit');
  'team_task_*'=@('team_task_create','team_task_get','team_task_list','team_task_update');
  'workflow'=@('workflow');
  'session_event_*'=@('session_event_read','session_event_search','session_event_trace');
  'session_search/trace'=@('session_search','session_trace');
  'goal'=@('create_goal','get_goal','update_goal');
  'mcp_gateway'=@('mcp_gateway','list_mcp_resources','list_mcp_resource_templates','read_mcp_resource');
  'spawn/team'=@('spawn_teammate','send_message','list_agents','wait_agent','interrupt_agent');
  'present'=@('present');
  'pwsh'=@('pwsh'); 'read'=@('read'); 'edit'=@('edit'); 'grep'=@('grep'); 'glob'=@('glob');
}
foreach($k in $toolGroups.Keys){$usage[$k]=0}
foreach($f in $files){
  try{
    $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
    $tt=$j.record.rows.contextTimeline.val.toolTally
    if(-not $tt){continue}
    $sess++
    $called = @($tt.PSObject.Properties | Where-Object {[double]$_.Value -gt 0} | ForEach-Object {$_.Name})
    foreach($k in $toolGroups.Keys){
      foreach($tn in $toolGroups[$k]){
        if($called -contains $tn){ $usage[$k]++; break }
      }
    }
  }catch{}
}
Write-Host "sessions with toolTally: $sess`n"
$toolGroups.Keys | ForEach-Object {
  $k=$_
  "{0,-24} used in {1,4}/{2} sessions = {3,5:N1}%" -f $k,$usage[$k],$sess,(100*$usage[$k]/$sess)
} | Sort-Object

