tool_input.content:
$dir = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"

$groups = @(
  [pscustomobject]@{ k='schedule';     t=@('schedule_create','schedule_delete','schedule_list','schedule_update','schedule_view','schedule_edit') },
  [pscustomobject]@{ k='team_task';    t=@('team_task_create','team_task_get','team_task_list','team_task_update') },
  [pscustomobject]@{ k='workflow';     t=@('workflow') },
  [pscustomobject]@{ k='session_event';t=@('session_event_read','session_event_search','session_event_trace') },
  [pscustomobject]@{ k='session_q';    t=@('session_search','session_trace') },
  [pscustomobject]@{ k='goal';         t=@('create_goal','get_goal','update_goal') },
  [pscustomobject]@{ k='mcp';          t=@('mcp_gateway','list_mcp_resources','list_mcp_resource_templates','read_mcp_resource') },
  [pscustomobject]@{ k='team_spawn';   t=@('spawn_teammate','send_message','list_agents','wait_agent','interrupt_agent') },
  [pscustomobject]@{ k='present';      t=@('present') },
  [pscustomobject]@{ k='pwsh';         t=@('pwsh') },
  [pscustomobject]@{ k='read';         t=@('read') },
  [pscustomobject]@{ k='edit';         t=@('edit') },
  [pscustomobject]@{ k='grep';         t=@('grep') },
  [pscustomobject]@{ k='glob';         t=@('glob') }
)

$cnt = @{}
foreach ($g in $groups) { $cnt[$g.k] = 0 }
$sess = 0
foreach ($f in $files) {
  try {
    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
    $tt = $j.record.rows.contextTimeline.val.toolTally
    if (-not $tt) { continue }
    $sess++
    $names = @($tt.PSObject.Properties | Where-Object { [double]$_.Value -gt 0 } | ForEach-Object { $_.Name })
    foreach ($g in $groups) {
      foreach ($tn in $g.t) {
        if ($names -contains $tn) { $cnt[$g.k]++; break }
      }
    }
  } catch {}
}

Write-Host "sessions with toolTally: $sess"
foreach ($g in $groups) {
  "{0,-14} used {1,4}/{2} = {3,5:N1}%" -f $g.k, $cnt[$g.k], $sess, (100 * $cnt[$g.k] / [Math]::Max(1,$sess))
}

tool_input.command:
$dir = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"
$gkeys = 'schedule','team_task','workflow','session_event','session_q','goal','mcp','team_spawn','present','pwsh','read','edit','grep','glob'
$gtool = @{}
$gtool['schedule']=@('schedule_create','schedule_delete','schedule_list','schedule_update','schedule_view','schedule_edit')
$gtool['team_task']=@('team_task_create','team_task_get','team_task_list','team_task_update')
$gtool['workflow']=@('workflow')
$gtool['session_event']=@('session_event_read','session_event_search','session_event_trace')
$gtool['session_q']=@('session_search','session_trace')
$gtool['goal']=@('create_goal','get_goal','update_goal')
$gtool['mcp']=@('mcp_gateway','list_mcp_resources','list_mcp_resource_templates','read_mcp_resource')
$gtool['team_spawn']=@('spawn_teammate','send_message','list_agents','wait_agent','interrupt_agent')
$gtool['present']=@('present');$gtool['pwsh']=@('pwsh');$gtool['read']=@('read');$gtool['edit']=@('edit');$gtool['grep']=@('grep');$gtool['glob']=@('glob')
$cnt=@{}; foreach($k in $gkeys){$cnt[$k]=0}
$sess=0
foreach($f in $files){
 try{
  $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
  $tt=$j.record.rows.contextTimeline.val.toolTally
  if(-not $tt){continue}
  $sess++
  $names=@($tt.PSObject.Properties | Where-Object {[double]$_.Value -gt 0} | ForEach-Object {$_.Name})
  foreach($k in $gkeys){ foreach($tn in $gtool[$k]){ if($names -contains $tn){$cnt[$k]++;break} } }
 }catch{}
}
Write-Host "sessions: $sess"
foreach($k in $gkeys){ "{0,-14} {1,4}/{2} = {3,5:N1}%" -f $k,$cnt[$k],$sess,(100*$cnt[$k]/$sess) }

$dir = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $dir -Filter "session-*.json"
$sched=0;$team=0;$wf=0;$ev=0;$sq=0;$goal=0;$mcp=0;$spawn=0;$pres=0;$pwshc=0;$readc=0;$editc=0;$grepc=0;$globc=0;$sess=0
foreach($f in $files){
 try{
  $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
  $tt=$j.record.rows.contextTimeline.val.toolTally
  if(-not $tt){continue}
  $sess++
  $n=@($tt.PSObject.Properties | Where-Object {[double]$_.Value -gt 0} | ForEach-Object {$_.Name})
  if($n|Where-Object{$_ -like 'schedule_*'}){$sched++}
  if($n|Where-Object{$_ -like 'team_task_*'}){$team++}
  if($n -contains 'workflow'){$wf++}
  if($n|Where-Object{$_ -like 'session_event_*'}){$ev++}
  if($n -contains 'session_search' -or $n -contains 'session_trace'){$sq++}
  if($n|Where-Object{$_ -in 'create_goal','get_goal','update_goal'}){$goal++}
  if($n|Where-Object{$_ -like 'mcp_gateway' -or $_ -like 'list_mcp*' -or $_ -like 'read_mcp*'}){$mcp++}
  if($n|Where-Object{$_ -in 'spawn_teammate','send_message','list_agents','wait_agent','interrupt_agent'}){$spawn++}
  if($n -contains 'present'){$pres++}
  if($n -contains 'pwsh'){$pwshc++}
  if($n -contains 'read'){$readc++}
  if($n -contains 'edit'){$editc++}
  if($n -contains 'grep'){$grepc++}
  if($n -contains 'glob'){$globc++}
 }catch{}
}
function P($name,$v,$s){"{0,-14} {1,4}/{2} = {3,5:N1}%" -f $name,$v,$s,(100*$v/[Math]::Max(1,$s))}
Write-Host "sessions: $sess"
P 'schedule' $sched $sess
P 'team_task' $team $sess
P 'workflow' $wf $sess
P 'session_event' $ev $sess
P 'session_search' $sq $sess
P 'goal' $goal $sess
P 'mcp' $mcp $sess
P 'team_spawn' $spawn $sess
P 'present' $pres $sess
P 'pwsh' $pwshc $sess
P 'read' $readc $sess
P 'edit' $editc $sess
P 'grep' $grepc $sess
P 'glob' $globc $sess
